const url = $input.first().json.url;
let downloadUrl = url;

if (url.includes('drive.google.com')) {
  const id = url.split('/d/')[1].split('/')[0];
  downloadUrl = `https://drive.google.com/uc?export=download&id=${id}`;
}

return { json: { url: downloadUrl } };

const binaries = Object.values($binary);

return binaries.map(file => ({
  json: {
    url: $json.url || ""
  },
  binary: {
    file
  }
}));

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  // Read the raw file from n8n's storage
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'file');

  // Create the Base64 string and save it as 'imageDataUrl'
  items[i].json.imageDataUrl = `data:${items[i].binary.file.mimeType};base64,${buffer.toString('base64')}`;
}

return items;

const items = $input.all();
let allData = [];

for (const item of items) {
  allData.push(item.json.content);
}

return [{
  json: { 
    all_evidence: allData 
  }
}];

const originalFiles = $('Merge 1').all();
const newClaimId = $input.first().json.id;

return originalFiles.map(file => {
  // Grab the string size and convert it to raw bytes safely
  let rawSize = file.binary.file.fileSize || "1024";
  let bytes = Math.round(parseFloat(rawSize) * (String(rawSize).includes('MB') ? 1048576 : (String(rawSize).includes('kB') ? 1024 : 1)));

  return {
    json: {
      claim_id: newClaimId,
      file_name: file.binary.file.fileName,
      mime_type: file.binary.file.mimeType,
      size_bytes: bytes
    },
    binary: file.binary
  };
});

// 1. SAFELY GRAB AND PARSE THE AI OUTPUT
let rawContent = $input.first().json.content; 

// Fallback: If you didn't use a "Set" node and wired the HTTP Request directly, this finds the text.
if (!rawContent && $input.first().json.choices) {
    rawContent = $input.first().json.choices[0].message.content;
}

let data = {};
let aiFailed = false;

try {
    // Strip markdown formatting just in case the AI disobeys instructions
    const cleanContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
    data = JSON.parse(cleanContent);
} catch (e) {
    // If the AI outputs complete garbage, we catch the crash safely here
    aiFailed = true;
}

// --- 2. SCHEMA VALIDATION ---
const required = ['policy_number', 'claimant_name', 'incident_date', 'incident_type', 'incident_description', 'claimed_amount'];
const missing = required.filter(field => !data[field]);
const errors = [];

if (data.claimed_amount && typeof data.claimed_amount !== 'number') errors.push('claimed_amount must be a number');
if (data.incident_date && !/^\d{4}-\d{2}-\d{2}$/.test(data.incident_date)) errors.push('invalid date format');

// --- 3. CONFIDENCE CALCULATION ---
const confidences = data.field_confidence || {};
const critical = ['policy_number', 'claimant_name', 'incident_date', 'claimed_amount'];

let critSum = 0, nonCritSum = 0, critCount = 0, nonCritCount = 0;

Object.keys(confidences).forEach(key => {
  if (critical.includes(key)) { critSum += confidences[key]; critCount++; }
  else { nonCritSum += confidences[key]; nonCritCount++; }
});

const avgCritical = critCount > 0 ? (critSum / critCount) : 0;
const avgNonCritical = nonCritCount > 0 ? (nonCritSum / nonCritCount) : 0;
const overallConfidence = (0.7 * avgCritical) + (0.3 * avgNonCritical);

// --- 4. FINAL VERDICT ---
data.overall_confidence = overallConfidence || 0;
data.validation_errors = errors;
data.missing_fields = missing;
data.ai_parsing_failed = aiFailed;

// If confidence is low, fields are missing, OR the AI returned bad JSON, flag for human review
data.needs_review = aiFailed || data.overall_confidence < 0.85 || missing.length > 0 || errors.length > 0;

// Pass it forward as a string so your downstream Supabase nodes remain perfectly intact
return [{
  json: {
    content: JSON.stringify(data)
  }
}];

// Grab the intact AI data from BEFORE the database lookup wiped it
const aiData = $('Quality Control').first().json;

// Grab the newly found Policy UUID
const policyData = $input.first().json;

// Attach the UUID safely into the AI package
aiData.real_policy_uuid = policyData.id;

return [{ json: aiData }];

